create or replace function vibe_private.blocked(other uuid) returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is null or not exists(select 1 from auth.users u where u.id=auth.uid() and u.email_confirmed_at is not null) or exists(select 1 from public.vibe_blocks where (user_id=auth.uid() and blocked_id=other) or (user_id=other and blocked_id=auth.uid())); $$;
create or replace function vibe_private.file_access(path text, writing boolean) returns boolean language plpgsql stable security definer set search_path='' as $$ declare parts text[]:=string_to_array(path,'/'); actor uuid:=auth.uid(); owner uuid; target uuid; begin if actor is null or array_length(parts,1)<>4 or vibe_private.blocked(actor) then return false; end if; begin owner:=parts[1]::uuid; target:=parts[3]::uuid; exception when invalid_text_representation then return false; end; if writing and owner<>actor then return false; end if; if parts[2]='profile' then return target=owner and not vibe_private.blocked(owner); elsif parts[2]='room' then return vibe_private.room_access(target) and not vibe_private.blocked(owner); elsif parts[2]='dm' then return (actor=owner or actor=target) and not vibe_private.blocked(case when actor=owner then target else owner end); end if; return false; end $$;
